/* @autogenerated */
import { computed, inject, Signal } from '@angular/core';
import { ActionRolesConfig, ActionsConfig } from '@shared/context/config/app-config.model';
import { APP_CONFIG } from '@shared/context/config/app-config.service';
import { grants } from '@shared/context/authorization-access/permission.service';
import { AppStateService } from '@shared/context/state/app-state.service';
import { UserInfo } from '@shared/context/identity/user-info.model';

/** Rol que deja la acción a todo el mundo, autenticado o no. */
export const ANY_ROLE = '*';

/**
 * Si el usuario tiene alguno de los roles que `actions.<kind>` pide para `entity`: los de la entidad o, si no
 * tiene, los generales. Sin configurar (o con `*`) se permite; con una lista vacía, a nadie.
 */
export function rolesAllow(config: ActionRolesConfig | undefined, entity: string, user: UserInfo | undefined): boolean {
  const roles = config?.entities?.[entity] ?? config?.roles;
  if (!roles || roles.includes(ANY_ROLE)) {
    return true;
  }
  return roles.some((role) => grants(user, role));
}

/**
 * Señal con el permiso por roles de la acción `kind` sobre la entidad: cambia con la configuración y el usuario.
 * `entity` se lee al evaluarla (las subclases asignan su definición después). Requiere contexto de inyección.
 */
export function actionRoles(kind: keyof ActionsConfig, entity: () => string, identity = 'main'): Signal<boolean> {
  const config = inject(APP_CONFIG);
  const user = inject(AppStateService).user(identity);
  return computed(() => rolesAllow(config().actions?.[kind], entity(), user()));
}
